"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import "./styles/cstrike.css";

interface RadarDot {
  x: number; // -1 to 1 (relative to center)
  y: number; // -1 to 1
  team: "ct" | "t" | "self";
  label?: string;
}

interface RadarProps extends React.HTMLAttributes<HTMLDivElement> {
  dots?: RadarDot[];
  size?: number;
  mapName?: string;
}

const Radar = React.forwardRef<HTMLDivElement, RadarProps>(
  ({ className, dots = [], size = 160, mapName, ...props }, ref) => {
    const center = size / 2;
    const radius = size / 2 - 4;

    return (
      <div
        ref={ref}
        className={cn("relative inline-block", className)}
        {...props}
      >
        <svg
          width={size}
          height={size}
          viewBox={`0 0 ${size} ${size}`}
          className="drop-shadow-lg"
        >
          {/* Background circle */}
          <circle
            cx={center}
            cy={center}
            r={radius}
            fill="rgba(0, 0, 0, 0.75)"
            stroke="var(--cs-border-light)"
            strokeWidth="2"
          />

          {/* Grid lines */}
          <line
            x1={center}
            y1={4}
            x2={center}
            y2={size - 4}
            stroke="var(--cs-border-dark)"
            strokeWidth="0.5"
            opacity="0.5"
          />
          <line
            x1={4}
            y1={center}
            x2={size - 4}
            y2={center}
            stroke="var(--cs-border-dark)"
            strokeWidth="0.5"
            opacity="0.5"
          />

          {/* Inner ring */}
          <circle
            cx={center}
            cy={center}
            r={radius * 0.5}
            fill="none"
            stroke="var(--cs-border-dark)"
            strokeWidth="0.5"
            opacity="0.3"
          />

          {/* Player dots */}
          {dots.map((dot, i) => {
            const dotX = center + dot.x * radius * 0.85;
            const dotY = center + dot.y * radius * 0.85;

            let fill: string;
            let dotSize: number;
            switch (dot.team) {
              case "self":
                fill = "#ffffff";
                dotSize = 4;
                break;
              case "ct":
                fill = "var(--cs-team-ct)";
                dotSize = 3;
                break;
              case "t":
                fill = "var(--cs-team-t)";
                dotSize = 3;
                break;
            }

            return (
              <g key={i}>
                {dot.team === "self" ? (
                  <>
                    {/* Self indicator - cross shape */}
                    <line
                      x1={dotX - 5}
                      y1={dotY}
                      x2={dotX + 5}
                      y2={dotY}
                      stroke={fill}
                      strokeWidth="2"
                    />
                    <line
                      x1={dotX}
                      y1={dotY - 5}
                      x2={dotX}
                      y2={dotY + 3}
                      stroke={fill}
                      strokeWidth="2"
                    />
                  </>
                ) : (
                  <circle cx={dotX} cy={dotY} r={dotSize} fill={fill} />
                )}
              </g>
            );
          })}
        </svg>

        {/* Map name label */}
        {mapName && (
          <div className="absolute bottom-1 left-1/2 -translate-x-1/2">
            <span className="cs-font-ui text-[8px] text-[var(--cs-text-dim)]">
              {mapName}
            </span>
          </div>
        )}
      </div>
    );
  }
);
Radar.displayName = "Radar";

export { Radar, type RadarDot, type RadarProps };

/* Counter-Strike 1.6 Design System */

/* CS 1.6 Logo Font - "Counter-Strike" by SoJa (free, public domain) */
@font-face {
  font-family: "Counter-Strike";
  src: url("/fonts/counter-strike.ttf") format("truetype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

/* ===== CS 1.6 VGUI Color System ===== */
:root {
  /* Primary olive-green backgrounds */
  --cs-bg: #4a5942;
  --cs-bg-secondary: #3e4637;
  --cs-bg-dark: #333433;
  --cs-bg-darker: #292929;
  --cs-bg-darkest: #1a1a1a;
  --cs-bg-control: #1a1a1a;
  --cs-bg-selection: #282e22;
  --cs-bg-list: #292929;

  /* Text colors */
  --cs-text: #dedfd6;
  --cs-text-secondary: #a0aa95;
  --cs-text-dim: #75806f;
  --cs-text-disabled: #282e22;
  --cs-text-control: #fffac1;
  --cs-text-bright: #ffc000;
  --cs-text-title: #ffde00;
  --cs-text-menu: #ffcc00;
  --cs-text-menu-hover: #ffffff;
  --cs-text-menu-active: #c0ba50;

  /* Accent colors */
  --cs-accent: #c4b550;
  --cs-accent-secondary: #958831;

  /* Border colors (3D bevel system) */
  --cs-border-light: #8c9284;
  --cs-border-dark: #292c21;
  --cs-border-outline: #000000;

  /* HUD colors (from GoldSrc engine hud.h) */
  --cs-hud-amber: #ffa000;
  --cs-hud-red: #ff1010;
  --cs-hud-green: #00a000;

  /* Team colors */
  --cs-team-ct: #99ccff;
  --cs-team-t: #ff4040;
  --cs-team-neutral: #cccccc;

  /* Slider/scrollbar */
  --cs-slider: #7f8c7f;
  --cs-slider-bg: #1f1f1f;
  --cs-scrollbar-track: #5a6a50;
}

/* ===== Font Classes ===== */
.cs-font-logo {
  font-family: "Counter-Strike", "Impact", sans-serif;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.cs-font-ui {
  font-family: "Verdana", "DejaVu Sans", system-ui, sans-serif;
  font-weight: 600;
  line-height: 1.5;
}

.cs-font-hud {
  font-family: "Courier New", "Courier", monospace;
  font-weight: 700;
  letter-spacing: 1px;
}

.cs-font-console {
  font-family: "Tahoma", "Geneva", sans-serif;
  font-size: 13px;
  line-height: 1.4;
}

/* ===== 3D Beveled Borders ===== */
.cs-bevel-raised {
  border-width: 2px;
  border-style: solid;
  border-top-color: var(--cs-border-light);
  border-left-color: var(--cs-border-light);
  border-bottom-color: var(--cs-border-dark);
  border-right-color: var(--cs-border-dark);
}

.cs-bevel-inset {
  border-width: 2px;
  border-style: solid;
  border-top-color: var(--cs-border-dark);
  border-left-color: var(--cs-border-dark);
  border-bottom-color: var(--cs-border-light);
  border-right-color: var(--cs-border-light);
}

/* ===== HUD Glow Effect ===== */
.cs-hud-glow {
  color: var(--cs-hud-amber);
  text-shadow:
    0 0 8px rgba(255, 160, 0, 0.6),
    0 0 16px rgba(255, 160, 0, 0.3);
}

.cs-hud-glow-red {
  color: var(--cs-hud-red);
  text-shadow:
    0 0 8px rgba(255, 16, 16, 0.6),
    0 0 16px rgba(255, 16, 16, 0.3);
}

.cs-hud-glow-green {
  color: var(--cs-hud-green);
  text-shadow:
    0 0 8px rgba(0, 160, 0, 0.6),
    0 0 16px rgba(0, 160, 0, 0.3);
}

/* ===== Text Shadow (VGUI style) ===== */
.cs-text-shadow {
  text-shadow: 1px 1px 0px rgba(0, 0, 0, 0.8);
}

/* ===== Panel Backgrounds ===== */
.cs-panel {
  background-color: var(--cs-bg);
}

.cs-panel-dark {
  background-color: var(--cs-bg-dark);
}

.cs-panel-control {
  background-color: var(--cs-bg-control);
}
